import { Injectable, Logger, NotFoundException } from '@nestjs/common';
import { createReadStream, type ReadStream } from 'node:fs';
import { mkdir, rm, stat, writeFile } from 'node:fs/promises';
import { dirname, resolve, sep } from 'node:path';
import { AppConfigService } from '../../config/app-config.service.js';

/**
 * Local-disk file storage under UPLOAD_DIR. Shared by every module that keeps
 * files (member photos now; documents, asset images later). Keys are
 * relative paths generated by the API, never by clients.
 *
 * Files are never served statically — modules stream them through
 * authenticated endpoints, because they include children's photos.
 */
@Injectable()
export class FileStorageService {
  private readonly logger = new Logger(FileStorageService.name);

  constructor(private readonly config: AppConfigService) {}

  async save(key: string, data: Buffer): Promise<void> {
    const path = this.pathFor(key);
    await mkdir(dirname(path), { recursive: true });
    await writeFile(path, data, { flag: 'wx' });
  }

  async open(key: string): Promise<{ stream: ReadStream; size: number }> {
    const path = this.pathFor(key);
    try {
      const { size } = await stat(path);
      return { stream: createReadStream(path), size };
    } catch {
      throw new NotFoundException('File not found');
    }
  }

  /** Best effort: a missing file is not an error (it may already be gone). */
  async remove(key: string): Promise<void> {
    try {
      await rm(this.pathFor(key), { force: true });
    } catch (err) {
      this.logger.warn(`Could not delete ${key}: ${String(err)}`);
    }
  }

  private pathFor(key: string): string {
    const root = this.config.uploadDir;
    const path = resolve(root, key);
    if (!path.startsWith(root + sep)) {
      throw new Error(`Storage key escapes the upload directory: ${key}`);
    }
    return path;
  }
}
